import type { ReactNode } from 'react';
import { cx } from '@/lib/cx';
import './badge.css';

/**
 * B23 · Badge — a small mono tag for CATEGORY metadata: environment,
 * plan, type, version. Never for live status — status is a StatusWord
 * (dot + word). Never for numbers that matter — those are stats.
 */
export interface BadgeProps {
  children: ReactNode;
  /** neutral (default) · seed — seed marks the CURRENT/active category. */
  tone?: 'neutral' | 'seed';
  className?: string;
}

export function Badge({ children, tone = 'neutral', className }: BadgeProps) {
  return (
    <span className={cx('sv-badge sv-mono', tone === 'seed' && 'sv-badge--seed', className)}>
      {children}
    </span>
  );
}

/* B23 · Badge — mono category tag. Rectilinear, never a pill. */

@layer sv-components {
  .sv-badge {
    display: inline-flex;
    align-items: center;
    padding: 2px 6px;
    border: 1px solid var(--sv-line);
    border-radius: var(--sv-r);
    background: var(--sv-wall);
    font-size: 9.5px;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--sv-ink-soft);
    white-space: nowrap;
  }

  .sv-badge--seed {
    border-color: var(--sv-seed-tint);
    background: var(--sv-seed-tint);
    color: var(--sv-seed-text);
  }
}
